#!/usr/bin/env python3
"""Static checks for luliy.me, run by .github/workflows/check.yml (and by hand before pushing).

The site has no build step, so a broken file goes live as soon as it reaches main. This catches the
common mistakes before that, in a few seconds and with no dependencies beyond Python and Node:

  1. JavaScript syntax: `node --check` on every .js / .mjs / .cjs file (vendor files included,
     since a truncated upload breaks them too).
  2. JSON: every .json and .webmanifest file parses.
  3. Python: every .py file compiles.
  4. Local references: src= / href= in the HTML pages, and the local "url" / "cover" / "src" entries
     in data/*.json, point at files that exist in the repository.
  5. _headers / _redirects: every line has the shape Cloudflare Pages expects.

Usage:  python3 .github/scripts/check_site.py          (exit code 1 on any problem)
"""
import json
import os
import re
import subprocess
import sys
from concurrent.futures import ThreadPoolExecutor
from html.parser import HTMLParser
from pathlib import Path
from urllib.parse import unquote, urlsplit

ROOT = Path(__file__).resolve().parent.parent.parent
# Generated copies of the blog (served as text, never as pages) and git internals are not checked.
SKIP_DIRS = {".git", "mirror", "node_modules", "__pycache__"}
problems = []


def rel(p):
    return p.relative_to(ROOT).as_posix()


def files(*suffixes):
    for dirpath, dirnames, filenames in os.walk(ROOT):
        dirnames[:] = sorted(d for d in dirnames if d not in SKIP_DIRS)
        for name in sorted(filenames):
            if name.endswith(suffixes):
                yield Path(dirpath) / name


def problem(path, msg):
    problems.append(f"{rel(path) if isinstance(path, Path) else path}: {msg}")


# ------------------------------------------------------------------ 1. JavaScript

def check_js():
    paths = list(files(".js", ".mjs", ".cjs"))

    def run(p):
        r = subprocess.run(["node", "--check", str(p)], capture_output=True, text=True)
        if r.returncode:
            first = next((l for l in r.stderr.splitlines() if "Error" in l), r.stderr.strip()[:200])
            problem(p, f"JavaScript syntax error: {first}")

    with ThreadPoolExecutor(max_workers=os.cpu_count() or 4) as pool:
        list(pool.map(run, paths))
    return len(paths)


# ------------------------------------------------------------------ 2. JSON

def check_json():
    n = 0
    for p in files(".json", ".webmanifest"):
        n += 1
        try:
            json.loads(p.read_text(encoding="utf-8"))
        except (ValueError, UnicodeDecodeError) as e:
            problem(p, f"invalid JSON: {e}")
    return n


# ------------------------------------------------------------------ 3. Python

def check_python():
    n = 0
    for p in files(".py"):
        n += 1
        try:
            compile(p.read_bytes(), str(p), "exec")
        except (SyntaxError, ValueError) as e:
            problem(p, f"Python syntax error: line {getattr(e, 'lineno', '?')}: {getattr(e, 'msg', e)}")
    return n


# ------------------------------------------------------------------ 4. Local references

class Refs(HTMLParser):
    ATTRS = {"src", "href", "poster", "data-src"}

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.refs = []
        self.in_template = 0

    def handle_starttag(self, tag, attrs):
        if tag == "template":
            self.in_template += 1
        for k, v in attrs:
            if k in self.ATTRS and v:
                self.refs.append((tag, v.strip()))

    def handle_endtag(self, tag):
        if tag == "template" and self.in_template:
            self.in_template -= 1


def local_target(base_dir, ref):
    """The repository file a reference points at, or None when it is not a local file reference."""
    if not ref or ref.startswith(("#", "data:", "blob:", "mailto:", "tel:", "javascript:", "about:", "{", "$")):
        return None
    if "${" in ref or "{{" in ref or "+" in ref and "'" in ref:
        return None  # built in script at run time
    parts = urlsplit(ref)
    if parts.scheme or parts.netloc:
        return None
    path = unquote(parts.path)
    if not path:
        return None
    target = (ROOT / path.lstrip("/")) if path.startswith("/") else (base_dir / path)
    return target.resolve()


# Paths answered by Cloudflare (Functions, redirects, router) rather than by a file.
VIRTUAL = ("gh/", "douban/", "article/", "post/", "cdn-cgi/")

# Known, harmless misses in pages generated by the local source project (fix them there, then drop them here).
KNOWN_MISSING = {
    # The page also loads ../fullscreen-control.*, which exists; these ./ copies only 404.
    ("works/kaoyan-dashboard/index.html", "./fullscreen-control.css?v=20261015-studies"),
    ("works/kaoyan-dashboard/index.html", "./fullscreen-control.js?v=20261015-studies"),
}


def exists(target):
    try:
        r = target.relative_to(ROOT).as_posix()
    except ValueError:
        return False  # points outside the repository
    if r.startswith(VIRTUAL) or r == ".":
        return True
    if target.is_file():
        return True
    if target.is_dir():
        return (target / "index.html").is_file()
    # Pages serves /foo for foo.html
    return target.with_name(target.name + ".html").is_file()


def check_html_refs():
    n = 0
    for p in files(".html"):
        if rel(p).startswith("assets/drive/"):
            continue  # vendor test page
        n += 1
        parser = Refs()
        try:
            parser.feed(p.read_text(encoding="utf-8"))
        except UnicodeDecodeError:
            problem(p, "not UTF-8")
            continue
        seen = set()
        for tag, ref in parser.refs:
            target = local_target(p.parent, ref)
            if target is None or ref in seen:
                continue
            seen.add(ref)
            if tag == "a" and not Path(urlsplit(ref).path).suffix:
                # plain page links: only check when they clearly name a file or folder in the repo
                if not urlsplit(ref).path.strip("/"):
                    continue
            if not exists(target) and (rel(p), ref) not in KNOWN_MISSING:
                problem(p, f"missing local file for <{tag}> {ref!r}")
    return n


def check_data_refs():
    data = ROOT / "data"
    n = 0
    for p in sorted(data.glob("*.json")):
        try:
            obj = json.loads(p.read_text(encoding="utf-8"))
        except ValueError:
            continue  # reported by check_json

        def walk(o):
            nonlocal n
            if isinstance(o, dict):
                for k, v in o.items():
                    if k in {"url", "cover", "src", "file"} and isinstance(v, str) and v.startswith(("./", "/")):
                        n += 1
                        target = local_target(ROOT, v)
                        if target is not None and not exists(target):
                            problem(p, f"{k} points at a missing file: {v}")
                    else:
                        walk(v)
            elif isinstance(o, list):
                for v in o:
                    walk(v)

        walk(obj)
    return n


# ------------------------------------------------------------------ 5. _headers / _redirects

def check_pages_config():
    for p in ROOT.rglob("_headers"):
        if any(part in SKIP_DIRS for part in p.parts):
            continue
        current = None
        for i, line in enumerate(p.read_text(encoding="utf-8").splitlines(), 1):
            if not line.strip() or line.lstrip().startswith("#"):
                continue
            if not line[0].isspace():
                current = line.strip()
                if not current.startswith(("/", "https://")):
                    problem(p, f"line {i}: a path must start with / ({line!r})")
            elif current is None or not re.match(r"^\s+!?[A-Za-z0-9-]+:", line):
                problem(p, f"line {i}: expected an indented 'Header-Name: value' under a path ({line!r})")
    p = ROOT / "_redirects"
    if p.exists():
        for i, line in enumerate(p.read_text(encoding="utf-8").splitlines(), 1):
            s = line.strip()
            if not s or s.startswith("#"):
                continue
            fields = s.split()
            if len(fields) not in (2, 3) or not fields[0].startswith("/"):
                problem(p, f"line {i}: expected 'from to [status]' ({s!r})")
            elif len(fields) == 3 and not re.fullmatch(r"(200|301|302|303|307|308|404)!?", fields[2]):
                problem(p, f"line {i}: unknown status {fields[2]!r}")


def main():
    counts = {
        "JavaScript files": check_js(),
        "JSON files": check_json(),
        "Python files": check_python(),
        "HTML pages": check_html_refs(),
        "data references": check_data_refs(),
    }
    check_pages_config()
    print("checked: " + ", ".join(f"{v} {k}" for k, v in counts.items()) + ", _headers, _redirects")
    if problems:
        print(f"\n{len(problems)} problem(s):")
        for line in sorted(problems):
            print("  " + line)
        if os.environ.get("GITHUB_ACTIONS"):
            for line in sorted(problems):
                path, _, msg = line.partition(": ")
                print(f"::error file={path}::{msg}")
        sys.exit(1)
    print("all good")


if __name__ == "__main__":
    main()
